@@ -1458,14 +1458,16 @@ cross_sigs (const char *email, kbnode_t a, kbnode_t b)
   return 1;
 }

+
 /* Return whether the key was signed by an ultimately trusted key.  */
 static int
-signed_by_utk (const char *email, kbnode_t a)
+signed_by_utk (ctrl_t ctrl, const char *email, kbnode_t keyblock)
 {
+  gpg_error_t err;
   kbnode_t n;
   int saw_email = 0;

-  for (n = a; n; n = n->next)
+  for (n = keyblock; n; n = n->next)
     {
       PKT_signature *sig;

@@ -1496,29 +1498,43 @@ signed_by_utk (const char *email, kbnode_t a)

       sig = n->pkt->pkt.signature;

-      if (! (sig->sig_class == 0x10
-             || sig->sig_class == 0x11
-             || sig->sig_class == 0x12
-             || sig->sig_class == 0x13))
-        /* Not a signature over a user id.  */
-        continue;
+      if (!IS_UID_SIG (sig))
+        continue; /* Not a signature over a user id.  */

-      /* SIG is on SIGNEE's keyblock.  If SIG was generated by the
-         signer, then it's a match.  */
-      if (tdb_keyid_is_utk (sig->keyid))
-        {
-          /* Match!  */
-          if (DBG_TRUST)
-            log_debug ("TOFU: %s is signed by an ultimately trusted key.\n",
-                       pk_keyid_str (a->pkt->pkt.public_key));
+      /* Check if SIG is on signee's keyblock.  If SIG was generated
+       * by the signer, then it's a match.  */
+      if (!tdb_keyid_is_utk (sig->keyid))
+        continue; /* Signature is not by an UTK.  */
+
+      /* Check that the signature is valid.  We treat anything under
+       * our min_cert_level as an invalid signature.  */
+      if(sig->sig_class >= SIGCLASS_CERT11
+         && sig->sig_class <= SIGCLASS_CERT13
+         && sig->sig_class - SIGCLASS_CERT < opt.min_cert_level)
+	continue;

-          return 1;
+      if ((err = check_key_signature (ctrl, keyblock, n, NULL)))
+	{
+          if (DBG_TRUST)
+            log_debug ("TOFU: %s has a bad signature claiming"
+                       " to be from an ultimately trusted key: %s\n",
+                       pk_keyid_str (keyblock->pkt->pkt.public_key),
+                       gpg_strerror (err));
+          continue;
         }
+
+      /* Match!  */
+      if (DBG_TRUST)
+        log_debug ("TOFU: %s is signed by an ultimately trusted key.\n",
+                   pk_keyid_str (keyblock->pkt->pkt.public_key));
+      return 1;
+
+
     }

   if (DBG_TRUST)
     log_debug ("TOFU: %s is NOT signed by an ultimately trusted key.\n",
-               pk_keyid_str (a->pkt->pkt.public_key));
+               pk_keyid_str (keyblock->pkt->pkt.public_key));

   return 0;
 }
